// ValidateCreateRequestBody runs the validations defined on CreateRequestBody
func ValidateCreateRequestBody(body *CreateRequestBody) (err error) {
	if body.DocumentIds == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("document_ids", "body"))
	}
	if body.ColumnsConfig == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("columns_config", "body"))
	}
	for _, e := range body.ColumnsConfig {
		if e != nil {
			if err2 := ValidateColumnConfigRequestBody(e); err2 != nil {
				err = loom.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidatePromptRequestBody runs the validations defined on PromptRequestBody
func ValidatePromptRequestBody(body *PromptRequestBody) (err error) {
	if body.Title == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("title", "body"))
	}
	return
}

// ValidateUpdateRequestBody runs the validations defined on UpdateRequestBody
func ValidateUpdateRequestBody(body *UpdateRequestBody) (err error) {
	for _, e := range body.ColumnsConfig {
		if e != nil {
			if err2 := ValidateColumnConfigRequestBody(e); err2 != nil {
				err = loom.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidateClearCellsRequestBody runs the validations defined on
// clear_cells_request_body
func ValidateClearCellsRequestBody(body *ClearCellsRequestBody) (err error) {
	if body.DocumentIds == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("document_ids", "body"))
	}
	return
}

// ValidateRegenerateCellRequestBody runs the validations defined on
// regenerate_cell_request_body
func ValidateRegenerateCellRequestBody(body *RegenerateCellRequestBody) (err error) {
	if body.DocumentID == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("document_id", "body"))
	}
	if body.ColumnIndex == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("column_index", "body"))
	}
	return
}

// ValidateColumnConfigRequestBody runs the validations defined on
// ColumnConfigRequestBody
func ValidateColumnConfigRequestBody(body *ColumnConfigRequestBody) (err error) {
	if body.Index == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("index", "body"))
	}
	if body.Name == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("name", "body"))
	}
	if body.Prompt == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("prompt", "body"))
	}
	if body.Format != nil {
		if !(*body.Format == "text" || *body.Format == "bulleted_list" || *body.Format == "number" || *body.Format == "currency" || *body.Format == "yes_no" || *body.Format == "date" || *body.Format == "tag" || *body.Format == "percentage" || *body.Format == "monetary_amount" || *body.Format == "company") {
			err = loom.MergeErrors(err, loom.InvalidEnumValueError("body.format", *body.Format, []any{"text", "bulleted_list", "number", "currency", "yes_no", "date", "tag", "percentage", "monetary_amount", "company"}))
		}
	}
	return
}
